<template><view class="page"><text class="eyebrow">PERSONALIZE</text><text class="h1">主题设置</text><text class="muted intro">选择你喜欢的保障体验</text><TpCard v-for="theme in themes" :key="theme.name" class="theme" :class="{selected:active===theme.name}" @click="active=theme.name"><view class="swatch" :style="{background:theme.color}"></view><view><text class="theme-name">{{theme.name}}</text><text class="muted">{{theme.desc}}</text></view><text v-if="active===theme.name" class="check">✓</text></TpCard><view class="button" @click="save">保存设置</view></view></template><script setup lang="ts">import {ref} from 'vue';import TpCard from '@/components/TpCard.vue';const themes=[{name:'薰衣草玻璃',desc:'当前推荐视觉',color:'#dcd8ff'},{name:'清透蓝',desc:'更轻盈的阅读体验',color:'#cde8ff'},{name:'暖阳米白',desc:'适合长辈阅读',color:'#f7e7cc'}];const active=ref(themes[0].name);const save=()=>{uni.showToast({title:'主题已保存',icon:'success'});setTimeout(()=>uni.navigateBack(),700)}</script><style scoped lang="scss">@import '@/styles/theme.scss';.h1,.intro{display:block;margin-top:14rpx}.intro{margin-bottom:30rpx}.theme{display:flex;align-items:center;gap:20rpx;margin-bottom:16rpx}.theme.selected{border:3rpx solid #6b5cf5}.swatch{width:68rpx;height:68rpx;border-radius:22rpx}.theme-name{display:block;font-size:29rpx;font-weight:700;margin-bottom:6rpx}.theme>view:nth-child(2){flex:1}.check{color:#6059cf;font-size:38rpx}.button{margin-top:40rpx}</style>
